class Solution {
public:
    bool canChoose(vector<vector<int>>& groups, vector<int>& nums) {
        int pos = 0;
        int n = nums.size();
        for (auto& g : groups) {
            int idx = kmpSearch(nums, pos, g);
            if (idx < 0) return false;
            pos = idx + (int)g.size();
        }
        return true;
    }
private:
    vector<int> computeLPS(const vector<int>& pat) {
        int m = pat.size();
        vector<int> lps(m, 0);
        int len = 0;
        int i = 1;
        while (i < m) {
            if (pat[i] == pat[len]) {
                lps[i++] = ++len;
            } else if (len > 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }
        return lps;
    }
    int kmpSearch(const vector<int>& nums, int start, const vector<int>& pat) {
        int m = pat.size();
        int n = nums.size();
        if (m == 0) return start;
        if (start + m > n) return -1;
        vector<int> lps = computeLPS(pat);
        int i = start, j = 0;
        while (i < n) {
            if (nums[i] == pat[j]) {
                i++;
                j++;
                if (j == m) return i - m;
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return -1;
    }
};
